"""Reports only completed retained evidence; phase tables remain reproducible."""
from pathlib import Path
import json,math
from thermo_continuity import sha,properties
from thermo_reference import parse_nasa
ROOT=Path(__file__).resolve().parents[1];P=ROOT/'candidateStudy/data/processed';DOC=ROOT/'docs'
def table(headers,rows):return '\n'.join(['| '+' | '.join(headers)+' |','|'+'|'.join(['---']*len(headers))+'|']+['| '+' | '.join(map(str,r))+' |' for r in rows])
def main():
    audit=json.loads((P/'mechanism_continuity_audit.json').read_text());refs=json.loads((P/'clean_thermo_reference.json').read_text());branch=json.loads((P/'clean_thermo_branch.json').read_text())
    rows=json.loads((P/'clean_thermo_campaign.json').read_text());success=[r for r in rows if 'signedEnergyDrift' in r]
    gri=json.loads((P/'clean_gri_campaign.json').read_text())
    native_limits=[];seen=set()
    for r in success+gri:
        if r.get('thermoControl')=='legacy' or 'signedEnergyDrift' not in r:continue
        path=ROOT/'candidateStudy/data/raw'/r['name']/'chemkin/therm.dat';digest=sha(path)
        if digest in seen:continue
        seen.add(digest);data=parse_nasa(path);species=[]
        for name,s in data.items():
            a,b=properties(s['low'],s['mid']),properties(s['high'],s['mid'])
            species.append(dict(species=name,Tcommon=s['mid'],jumps={k:b[k]-a[k] for k in a}))
        native_limits.append(dict(label=('GRI' if r.get('mechanism')=='installedGRI' else 'H2')+'_'+r['thermoControl'],
          sourcePath=str(path.relative_to(ROOT)),sourceSHA256=digest,species=species,maxAbsJumps={k:max(abs(s['jumps'][k]) for s in species) for k in ['Cp','h','s','g']}))
    (P/'native_thermo_control_limits.json').write_text(json.dumps(dict(driverSHA256=sha(__file__),records=native_limits,scope='Actual serialized native control files. Molar units use installed Ru; direct polynomial limits, independent of native property implementation.'),indent=2)+'\n')
    doc=['# Mechanism continuity audit','', 'Pinned Cantera 3.2 independent property evaluation accompanies direct NASA7 limits. All quantities below use the common legacy Ru=8314.47006650545 J/(kmol K); reference reactor trajectories retain their declared physical constants. No mechanism with different kinetics supplies a thermo-only error estimate.','',table(['Mechanism','Species / reactions','Largest specific h jump (J/kg)','Species','Largest relative K jump'],[[r['name'],f"{r['nSpecies']} / {r['nReactions']}",f"{r['rankedEnthalpy'][0]['deltaHSpecific']:+.9g}",r['rankedEnthalpy'][0]['species'],f"{r['largestRelativeKJump']:.9g}"] for r in audit['mechanisms']]),'',f"{len(audit['retainedCoefficientSets'])} unique coefficient-file sets from retained cases are audited with their original use lists and hashes. The full property/reaction ranking and mixture examples are in mechanism_continuity_audit.json. Sampling dates and licensing/provenance are retained in MechanismContinuity_v2. Modern Alzueta baseline includes 281 reactions; modified linear-Burke phase is excluded.", '', 'For each switch, Delta h_r=sum nu_ir Delta h_i and Delta ln K=−sum nu_ir Delta g_i/(Ru Tc). Kp/Kc have the same multiplicative jump at a fixed temperature. For fixed composition, Delta ha=sum Yi Delta h_i/W_i, and Delta ea=Delta ha because R(Y)Tc is continuous. Mixture examples use the actual unburned and radical mixtures and an explicitly artificial equal-mole mixture.', '', 'The HS control leaves Cp unchanged. CpHS additionally shifts its high-branch constant coefficient. Both preserve low/reference coefficients exactly; serialized h jumps are below 2.8e-5 J/kmol. These are internally continuous to reported serialization precision, not exact-real arithmetic or independently validated source-data fits. Cp positivity extrema were computed with polynomial roots; no interval-certified positivity theorem is asserted for every imported species.']
    for mech in audit['mechanisms']:
        doc+=['',f"## {mech['name']}: every species midpoint",'',table(['Species','Tc (K)','Delta Cp','Delta h','Delta s','Delta g'],[[r['species'],r['Tcommon'],*[f"{r['jumps'][k]:+.8e}" for k in ['Cp','h','s','g']]] for r in mech['species']]),'','Cp and s units: J/(kmol K); h and g: J/kmol.']
    (DOC/'mechanism_continuity_audit.md').write_text('\n'.join(doc)+'\n')
    with (DOC/'mechanism_continuity_audit.md').open('a') as f:
        f.write('\n## Actual serialized native controls\n\n'+table(['Control','Max |Delta Cp|','Max |Delta h|','Max |Delta s|','Max |Delta g|'],[[r['label']]+[f"{r['maxAbsJumps'][k]:.8e}" for k in ['Cp','h','s','g']] for r in native_limits])+'\n\nCp/s: J/(kmol K); h/g: J/kmol. Full species limits and exact file hashes are in native_thermo_control_limits.json. This supplement includes the GRI CpHS file produced after the immutable mechanism-wide audit.\n')
    output=['# Clean versus legacy thermochemistry','', 'The original pressure/density/enthalpy defect survives continuous thermochemistry. The direct breakpoint source floor is removed, while a small number of spatial source failures remain under the unchanged 1e-10 criterion. Therefore continuity repair alone is not a complete source-integration or CFD correction.','',f"This report currently includes {len(success)} completed matched H2 attribution records (18 planned including reused legacy controls), {len(branch)} direct native controls, and {len(refs['records'])} independent CV/physical-CP trajectories. It reports completed runs only; pending cases are not interpreted.", '', 'The kinetic input text, low/reference thermo, transport, initial T/p/U/species, grid, Euler/upwind discretization and source settings are held fixed within each matched pair. Changing entropy/enthalpy affects equilibrium-derived reverse rates; this is an unavoidable thermochemistry-driven trajectory interaction. No original run or accepted source is edited. The original transport remains As=Ts=0.', '', '## Endpoint and local attribution', '',table(['Source','Closure','dt (us)','Thermo','Energy drift (%)','Mean T (K)','rho hs + rho hc (J)','Source fails / calls'],[[r['sourcePathControl'],r['mode'],r['dt']*1e6,r['thermoControl'],f"{100*r['signedEnergyDrift']:+.9f}",f"{r['meanTemperature']:.9f}",f"{r['cellCumulativeTerms']['DrhoH']+r['cellCumulativeTerms']['DrhoC']:+.10e}",f"{r.get('failedSourceEnergyCalls','unobserved')} / {r.get('sourceCalls','unobserved')}"] for r in success]),'', 'Native costOde source endpoints were not traced; its cellwise species/Qdot identity is measured. CV source entries test the actual accepted endpoint energy with J/m3 units and the original relative denominator max(|E_initial|,1 J/m3). The source diagnostic is separate from the CFD ledger and must not be added again as external heat.', '']
    for source in ['native','CV']:
     for dt in [2e-6,1e-6]:
        group=[r for r in success if r['sourcePathControl']==source and r['dt']==dt and r['mode']=='none']
        if not group:continue
        output+=[f"## {source}, dt={dt*1e6:g} us: same eight-term budget",'',table(['Quantity (J)']+[r['thermoControl'] for r in group],[[k]+[f"{r['cumulativeTerms'][k]:+.12e}" for r in group] for k in ['Dpressure','Dkinetic','DrhoH','DrhoC','DspeciesChemistry','Dequation','Dtransport','Dhistory']]+[['Endpoint change']+[f"{r['end']['E_stored']-r['initial']['E_stored']:+.12e}" for r in group],['Max step closure']+[f"{r['maxStepClosure']:.4e}" for r in group],['Max cell closure']+[f"{r['maxCellClosure']:.4e}" for r in group]]),'']
    source_groups=[]
    for thermo in ['legacy','HS','CpHS']:
        group=[r for r in success if r['sourcePathControl']=='CV' and r['thermoControl']==thermo]
        source_groups.append([thermo,sum(r['failedSourceEnergyCalls'] for r in group),sum(r['sourceCalls'] for r in group),f"{max(r['maxSourceRelativeEnergyChange'] for r in group):.8e}"])
    output+=['## Unchanged spatial source gate','',table(['Thermo','Failed CV calls','Total CV calls','Largest relative energy change'],source_groups),'','Each completed thermo row combines the same four CV configurations (two timesteps and two coupling modes). All use the unchanged 1e-10 relative source-energy gate. Native costOde endpoint source energy is not traced and is not included in these totals. The successful removal of the direct breakpoint floor does not turn the remaining failures into passes.','', '## Finite chemistry transfer and conservative-state ledger','',table(['Source','Mode','dt (us)','Thermo','Dchemistry (J)','Max source relative error'],[[r['sourcePathControl'],r['mode'],r['dt']*1e6,r['thermoControl'],f"{r['cellCumulativeTerms']['Dchemistry']:+.8e}",f"{r['maxSourceRelativeEnergyChange']:.8e}" if 'maxSourceRelativeEnergyChange' in r else 'not traced'] for r in success]),'', 'Dchemistry is the finite formation-transfer cancellation in the CFD equations. It is distinct from the absolute-energy residual of a standalone chemistry state. An algebraically consistent RR/Qdot pair can coexist with an inaccurate thermodynamic state or later coupling defect.']
    for dt in [2e-6,1e-6]:
        group=[r for r in success if r['sourcePathControl']=='CV' and r['mode']=='conservativeState' and r['dt']==dt]
        if not group:continue
        output+=['',f'### Corrected CV ledger, dt={dt*1e6:g} us','',table(['Quantity (J)']+[r['thermoControl'] for r in group],[[k]+[f"{r['cellCumulativeTerms'][k]:+.10e}" for r in group] for k in group[0]['cellCumulativeTerms']]+[['Endpoint change']+[f"{r['end']['E_stored']-r['initial']['E_stored']:+.10e}" for r in group],['Max cell closure']+[f"{r['maxCellClosure']:.4e}" for r in group]])]
    output+=['','## GRI: independently matched full-flow controls','', 'The identical GRI kinetics and initial fields are retained within each legacy/CpHS pair. This tests generalization of the coupling attribution; its different kinetics and constants prevent using H2-versus-GRI drift as a thermo-only difference.','',table(['dt (us)','Thermo','Energy drift (%)','rho hs (J)','rho hc (J)','Mean T (K)','Max step closure (J)'],[[r['dt']*1e6,r['thermoControl'],f"{100*r['signedEnergyDrift']:+.9f}",f"{r['cumulativeTerms']['DrhoH']:+.8e}",f"{r['cumulativeTerms']['DrhoC']:+.8e}",f"{r['meanTemperature']:.6f}",f"{r['maxStepClosure']:.4e}"] for r in gri if 'signedEnergyDrift' in r])]
    for dt in [2e-6,1e-6]:
        group=[r for r in gri if 'signedEnergyDrift' in r and r['dt']==dt]
        if not group:continue
        output+=['',f'### GRI dt={dt*1e6:g} us: eight-term budget','',table(['Quantity (J)']+[r['thermoControl'] for r in group],[[k]+[f"{r['cumulativeTerms'][k]:+.12e}" for r in group] for k in ['Dpressure','Dkinetic','DrhoH','DrhoC','DspeciesChemistry','Dequation','Dtransport','Dhistory']]+[['Endpoint change']+[f"{r['end']['E_stored']-r['initial']['E_stored']:+.12e}" for r in group]])]
    interactions=[]
    bykey={(r['thermoControl'],r['mode'],r['dt']):r for r in success if r['sourcePathControl']=='CV'}
    for dt in [2e-6,1e-6]:
     for clean in ['HS','CpHS']:
        keys=[(clean,'conservativeState',dt),('legacy','conservativeState',dt),(clean,'none',dt),('legacy','none',dt)]
        if not all(k in bykey for k in keys):continue
        cases=[bykey[k] for k in keys]
        values={'Endpoint change':[r['end']['E_stored']-r['initial']['E_stored'] for r in cases]}
        values.update({k:[r['cellCumulativeTerms'][k] for r in cases] for k in cases[0]['cellCumulativeTerms']})
        for k,v in values.items():interactions.append(dict(dt=dt,clean=clean,quantity=k,interaction=v[0]-v[1]-v[2]+v[3],units='J'))
    (P/'clean_thermo_interactions.json').write_text(json.dumps(dict(definition='[D(clean,G)-D(legacy,G)]-[D(clean,none)-D(legacy,none)]',records=interactions,inputSHA256=sha(P/'clean_thermo_campaign.json')),indent=2)+'\n')
    output+=['','## Source invariants and independent checks','',table(['Constraint / mechanism','T0','rtol','Invariant change (relative)','Jump-subtracted remainder'],[[r['constraint']+' / '+r['mechanism'],r['Tinitial'],r['rtol'],f"{r['relativeInvariantChange']:.8e}",f"{r['jumpSubtractedRelativeError']:.8e}"] for r in refs['records'] if r['rtol']==1e-12]),'', 'Direct native HS/CpHS controls cross 1000 K from 999 K without the persistent legacy 1.146e-7 floor. Independent Cantera confirms removal. The remaining native spatial failures for continuous data are retained, including calls wholly above 1000 K. Endpoint noncrossing still cannot exclude internal excursions; the trace does not uniquely resolve stage error. The full CpHS control removes Cp jumps to floating precision but does not make an adaptive ODE tolerance a certified nonlinear energy-invariant tolerance.', '', '## Hierarchical attribution and measured interaction','', 'These are distinct mechanisms with interacting trajectories. The source jump follows an event identity in 0D and disappears under matched continuity controls. The CFD density pair remains after that change. Local reactor and global CFD normalizations differ and are not directly subtracted.', '', 'The exact eight-term identity is additive within a particular executed CFD trajectory. A thermo-only difference is an intervention that changes temperature, density, rates and all subsequent operators. It cannot be universally assigned as an independent additive E_data term on the original trajectory. For a two-factor comparison, define I=[D(clean,G)−D(legacy,G)]−[D(clean,none)−D(legacy,none)] with all four D measured in joules. Nonzero I records the data/coupling interaction; it is not an unmeasured residual category. The conservative closure also has DpostH/DpostC in its corrected-state identity, reported above rather than silently forced into the unmodified eight terms.','',table(['dt (us)','Clean control','Quantity','Measured interaction (J)'],[[r['dt']*1e6,r['clean'],r['quantity'],f"{r['interaction']:+.9e}"] for r in interactions if r['quantity'] in ['Endpoint change','DrhoH','DrhoC','Dpressure','Dkinetic','DpostH','DpostC']]),'', 'The hierarchy is data-event identity in 0D, chemistry integration residual under fixed data, algebraic finite source cancellation, then executed CFD operator budget. Only measured interventions supply cross-effect estimates. This establishes a surviving coupling mechanism, not statistical independence or a universal additive taxonomy.', '', '## Candidate cycles after the mandatory deliverable','', 'The initial completed-control report preceded the valid-data projection prototype. The subsequent 48-case scalar baseline and five-family decisions are reported in invariant_projection_results.md, finite_source_map_results.md and thermochemical_risk_results.md. Generic projection novelty, unconditional accuracy dominance, finite-RR novelty, interface sufficiency, mechanism-only certification and physical-accuracy repair claims fail their stated gates. No new correction is promoted. Pressure/transport coupling with resolved accuracy remains the relevant research pivot.', '', '## Trusted mechanism scope','', 'Installed GRI has both full-flow matched controls and independent Cantera replay. The independently distributed Alzueta 2023 baseline is audited and its CV/physical-CP trajectories are retained. Fourteen native export attempts preserve every parser failure: quoted comments/CRLF, global thermo header/width, element case, then the substantive unsupported PLOG reaction form. Dropping PLOG would change kinetics and is not done. Native modern full-flow validation is therefore unavailable in this v2012 reader; the independent mechanism is used in the source hierarchy.', '', '## Provenance and decision','', 'Machine-readable tables: clean_thermo_campaign.json, clean_gri_campaign.json, clean_thermo_branch.json, clean_thermo_reference.json, clean_thermo_interactions.json and mechanism_continuity_audit.json. Inputs, native source/library/executable snapshots and raw rank traces are retained. Historical 38 evidence criteria and 499 frozen actionStudy files remain protected. Source failures and parser failures are not relabeled as publication successes. No claim of physical source-data accuracy, universal independence, solved local reacting accuracy or publication-gate survival follows.']
    (DOC/'clean_vs_legacy_results.md').write_text('\n'.join(output)+'\n')
    sources=['clean_thermo_campaign.json','clean_gri_campaign.json','clean_thermo_branch.json','clean_thermo_reference.json','mechanism_continuity_audit.json','clean_thermo_interactions.json','native_thermo_control_limits.json']
    (P/'clean_thermo_report_sources.json').write_text(json.dumps(dict(driverSHA256=sha(__file__),inputs={name:sha(P/name) for name in sources},completedMatchedRecords=len(success)),indent=2)+'\n')
    print('Reported completed records',len(success),flush=True)
if __name__=='__main__':main()
